import sys, json

data = sys.stdin.read()
with open('after-cpm-packages.json', 'w') as f:
    f.write(data)

after = json.loads(data)
before = json.load(open('baseline-packages.json'))

# Build lookup: (project, framework, package) -> version
def build_map(d):
    m = {}
    for proj in d.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                m[(pname, fw['framework'], pkg['id'])] = pkg['resolvedVersion']
    return m

bm = build_map(before)
am = build_map(after)

all_keys = sorted(set(bm.keys()) | set(am.keys()))
changes = []
unchanged = []
for k in all_keys:
    bv = bm.get(k)
    av = am.get(k)
    if bv != av:
        changes.append((k[0], k[2], k[1], bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((k[0], k[2], k[1], av))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]} [{c[2]}] {c[1]}: {c[3]} -> {c[4]}')
else:
    print('  None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]} [{u[2]}] {u[1]}: {u[3]}')
"

